Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Ẋ — lateral velocity <span id="velXval" style="font-size:10px;color:#555">-0.5</span>
  <input type="range" id="velX" min="-2" max="2" step="0.1" value="-0.5"></label>
<label>Ẏ — vertical velocity <span id="velYval" style="font-size:10px;color:#555">1</span>
  <input type="range" id="velY" min="-2" max="2" step="0.1" value="1"></label>
<label>Ż — depth velocity <span id="velZval" style="font-size:10px;color:#555">-1</span>
  <input type="range" id="velZ" min="-2" max="2" step="0.1" value="-1"></label>
<div style="margin-top:6px;font-weight:bold">Demo steps</div>
<button id="step0" class="active">1 · As drawn in the book</button>
<button id="step1">2 · Pure lateral motion</button>
<button id="step2">3 · Pure depth motion</button>
<div id="narration" style="font-size:11px;color:#333;max-width:100%;margin-top:4px"></div>
<div style="font-size:10px;color:#777;margin-top:6px">Drag the black point P to move it in 3D. Drag elsewhere to orbit.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// ── Element spec ─────────────────────────────────────────────────────────
// O              → SphereGeometry(0.18) black, at origin
// image plane    → PlaneGeometry(3,4) grey #cccccc opacity 0.2 at z=2 + #444 frame
// P              → SphereGeometry(0.18) black, draggable
// p              → SphereGeometry(0.11) black, ON the plane (reprojection)
// solid ray      → Line #33dd33, O → 1.08·P
// dashed ray     → Line LineDashedMaterial #33dd33, O → P'
// Ṗ arrow        → ArrowHelper #ee1111 at P along s·Ṗ
// ṗ arrow        → ArrowHelper #ee1111 at p toward p' (in the plane)
// labels         → addLabel serif italic: o, P, p, Ṗ, ṗ

const F = 2;
const S = 1.2; // velocity display scale
const state = {
  P: new THREE.Vector3(0.8, 0.9, 7),
  vel: new THREE.Vector3(-0.5, 1, -1),
};

// ── Static geometry ─────────────────────────────────────────────────────
const matBlack = new THREE.MeshBasicMaterial({ color: 0x111111 });
const sphO = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 16), matBlack);
scene.add(sphO);

const planeGeo = new THREE.PlaneGeometry(3, 4);
const planeMesh = new THREE.Mesh(planeGeo,
  new THREE.MeshBasicMaterial({ color: 0xcccccc, transparent: true, opacity: 0.2, side: THREE.DoubleSide, depthWrite: false }));
planeMesh.position.set(0, 0, F);
scene.add(planeMesh);
const framePts = [
  new THREE.Vector3(-1.5, -2, F), new THREE.Vector3(1.5, -2, F),
  new THREE.Vector3(1.5, 2, F), new THREE.Vector3(-1.5, 2, F),
  new THREE.Vector3(-1.5, -2, F)];
scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(framePts),
  new THREE.LineBasicMaterial({ color: 0x444444 })));

// ── Dynamic geometry ────────────────────────────────────────────────────
const sphP = new THREE.Mesh(new THREE.SphereGeometry(0.18, 24, 16), matBlack);
scene.add(sphP);
const sphp = new THREE.Mesh(new THREE.SphereGeometry(0.11, 24, 16), matBlack);
scene.add(sphp);

const raySolid = new THREE.Line(new THREE.BufferGeometry(),
  new THREE.LineBasicMaterial({ color: 0x33dd33 }));
scene.add(raySolid);
const rayDash = new THREE.Line(new THREE.BufferGeometry(),
  new THREE.LineDashedMaterial({ color: 0x33dd33, dashSize: 0.25, gapSize: 0.15 }));
scene.add(rayDash);

const arrowP = new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(), 1, 0xee1111, 0.35, 0.2);
scene.add(arrowP);
const arrowp = new THREE.ArrowHelper(new THREE.Vector3(0, 1, 0), new THREE.Vector3(), 1, 0xee1111, 0.22, 0.13);
scene.add(arrowp);

registerInteractive(sphP, {
  title: 'Point P in 3D',
  body: 'Drag me. The image point p always sits where the viewing ray from O pierces the image plane at z = f.',
  tooltip: 'Drag to move P'
});

// ── Labels (positions updated in recompute) ─────────────────────────────
const serif = { color: '#111', fontSize: '15px' };
const lblO = addLabel('<i>o</i>', new THREE.Vector3(-0.35, -0.45, 0), serif);
const lblP = addLabel('<b>P</b>', new THREE.Vector3(), serif);
const lblp = addLabel('<i>p</i>', new THREE.Vector3(), serif);
const lblPd = addLabel('<i>Ṗ</i>', new THREE.Vector3(), { ...serif, fontSize: '17px' });
const lblpd = addLabel('<i>ṗ</i>', new THREE.Vector3(), { ...serif, fontSize: '17px' });

// ── Recompute everything from (P, Ṗ) ────────────────────────────────────
const _origin = new THREE.Vector3(0, 0, 0);
function recompute() {
  const P = state.P, v = state.vel;
  // image point p = (fX/Z, fY/Z, f)
  const t = F / P.z;
  const p = new THREE.Vector3(P.x * t, P.y * t, F);
  sphP.position.copy(P);
  sphp.position.copy(p);

  // solid ray: O → 8% past P
  const ext = P.clone().multiplyScalar(1.08);
  raySolid.geometry.dispose();
  raySolid.geometry = new THREE.BufferGeometry().setFromPoints([_origin, ext]);

  // displaced point and its reprojection
  const Pd = P.clone().addScaledVector(v, S);
  const td = F / Math.max(Pd.z, 0.3);
  const pd = new THREE.Vector3(Pd.x * td, Pd.y * td, F);

  rayDash.geometry.dispose();
  rayDash.geometry = new THREE.BufferGeometry().setFromPoints([_origin, Pd]);
  rayDash.computeLineDistances();

  // Ṗ arrow at P
  const vlen = v.length();
  if (vlen > 1e-4) {
    arrowP.visible = true;
    arrowP.position.copy(P);
    arrowP.setDirection(v.clone().normalize());
    arrowP.setLength(S * vlen, 0.35, 0.2);
  } else arrowP.visible = false;

  // ṗ arrow at p toward p' (in the plane)
  const flow = pd.clone().sub(p); flow.z = 0;
  const flen = flow.length();
  if (flen > 1e-4) {
    arrowp.visible = true;
    arrowp.position.copy(p);
    arrowp.setDirection(flow.clone().normalize());
    arrowp.setLength(flen, Math.min(0.22, flen * 0.5), Math.min(0.13, flen * 0.3));
  } else arrowp.visible = false;

  // labels
  lblP.pos.copy(P).add(new THREE.Vector3(0.45, -0.1, 0));
  lblp.pos.copy(p).add(new THREE.Vector3(0.35, -0.35, 0));
  lblPd.pos.copy(P).addScaledVector(v, S).add(new THREE.Vector3(0, 0.35, 0));
  lblpd.pos.copy(p).addScaledVector(flow, 1).add(new THREE.Vector3(-0.2, 0.3, 0));
}
recompute();

// ── Camera (perspective) ────────────────────────────────────────────────
setCameraView({
  projection: 'perspective',
  azimuthDeg: 20, elevationDeg: 12, rollDeg: 0,
  target: [0.4, 0.2, 3.5],
  heightFraction: 0.6, distanceScale: 1.1,
});

// ── Sliders ─────────────────────────────────────────────────────────────
function bindSlider(id, comp) {
  const el = document.getElementById(id);
  const val = document.getElementById(id + 'val');
  el.addEventListener('input', () => {
    state.vel[comp] = parseFloat(el.value);
    val.textContent = el.value;
    recompute();
  });
}
bindSlider('velX', 'x'); bindSlider('velY', 'y'); bindSlider('velZ', 'z');

// ── Demo steps ──────────────────────────────────────────────────────────
const STEPS = [
  { title: 'As drawn in the book', vel: [-0.5, 1, -1],
    narration: "The figure's configuration: Ṗ has vertical and toward-camera components. The dashed ray to P+Ṗ pierces the plane exactly at the tip of the ṗ arrow." },
  { title: 'Pure lateral motion', vel: [1.5, 0, 0],
    narration: 'Only Ẋ nonzero: ṗ becomes horizontal with magnitude f·Ẋ/Z — a clean rescaling.' },
  { title: 'Pure depth motion', vel: [0, 0, -1.5],
    narration: "Only Ż nonzero: p drifts outward from the principal point even though P's X and Y never change — perspective division turns approach into looming expansion." },
];
let _tween = null;
function goToStep(i) {
  const st = STEPS[i];
  ['step0', 'step1', 'step2'].forEach((id, j) =>
    document.getElementById(id).classList.toggle('active', j === i));
  document.getElementById('narration').textContent = st.narration;
  const from = state.vel.clone();
  const to = new THREE.Vector3(...st.vel);
  if (_tween) cancelAnimationFrame(_tween);
  const t0 = performance.now();
  const step = (now) => {
    const k = Math.min(1, (now - t0) / 600);
    const e = k * (2 - k);
    state.vel.lerpVectors(from, to, e);
    ['velX', 'velY', 'velZ'].forEach((id, j) => {
      const val = state.vel.getComponent(j);
      document.getElementById(id).value = val;
      document.getElementById(id + 'val').textContent = val.toFixed(1);
    });
    recompute();
    if (k < 1) _tween = requestAnimationFrame(step);
  };
  _tween = requestAnimationFrame(step);
}
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
document.getElementById('narration').textContent = STEPS[0].narration;

// ── Drag P on a plane parallel to the image plane at P.z ────────────────
const _dragRay = new THREE.Raycaster();
const _ndc = new THREE.Vector2();
let _dragging = false;
function _setNdc(e) {
  const r = canvas.getBoundingClientRect();
  _ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  _ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (e) => {
  _setNdc(e);
  _dragRay.setFromCamera(_ndc, camera);
  if (_dragRay.intersectObject(sphP).length) {
    _dragging = true;
    controls.enabled = false;
    canvas.setPointerCapture(e.pointerId);
  }
});
canvas.addEventListener('pointermove', (e) => {
  if (!_dragging) return;
  _setNdc(e);
  _dragRay.setFromCamera(_ndc, camera);
  const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), -state.P.z);
  const hit = new THREE.Vector3();
  if (_dragRay.ray.intersectPlane(dragPlane, hit)) {
    state.P.x = Math.max(-2, Math.min(3, hit.x));
    state.P.y = Math.max(-2, Math.min(2.5, hit.y));
    recompute();
  }
});
window.addEventListener('pointerup', () => {
  if (_dragging) { _dragging = false; controls.enabled = true; }
});
// @FIGURE_CODE_END

