const _dashGeo = new THREE.CylinderGeometry(1, 1, 1, 8);
const _up = new THREE.Vector3(0, 1, 0);
function setCylBetween(mesh, a, b, r) {
  const dir = b.clone().sub(a);
  const len = dir.length();
