  const total = a.distanceTo(b);
  const dashLen = 0.3, gap = 0.2, step = dashLen + gap;
  const dir = b.clone().sub(a).normalize();
  for (let t = 0; t < total; t += step) {
    const t1 = Math.min(t + dashLen, total);
    if (t1 - t < 0.05) break;
    const m = new THREE.Mesh(_dashGeo, matGreen);
    setCylBetween(m, a.clone().addScaledVector(dir, t), a.clone().addScaledVector(dir, t1), r);
