// @FIGURE_CODE_BEGIN
// ── Element spec ─────────────────────────────────────────────────────────
// O              → SphereGeometry(0.2) black, at origin
// image plane    → PlaneGeometry(3.6,4.6) grey #cccccc opacity 0.22 at z=2,
//                  border = 4 thick cylinders r=0.035 #444 (bold outline)
// P              → SphereGeometry(0.2) black, draggable, far right of plane
// p              → SphereGeometry(0.12) black, ON the plane (reprojection)
// solid ray      → thick CylinderGeometry r=0.05 #33dd33, O → 1.08·P
// dashed ray     → chain of CylinderGeometry segments r=0.05 #33dd33, O → P'
// Ṗ arrow        → custom thick arrow (cylinder shaft r=0.065 + cone) #ee1111 at P along s·Ṗ
// ṗ arrow        → custom thick arrow (cylinder shaft r=0.05 + cone) #ee1111 at p toward p'
// labels         → addLabel large serif: o, P, p, Ṗ, ṗ (ṗ anchored at arrow tip)

const F = 2;
const S = 1.7;              // velocity display scale (enlarged for prominence)
const RAY_R = 0.05;
const state = {
  P: new THREE.Vector3(0.8, 0.9, 7),
  vel: new THREE.Vector3(-0.5, 1, -1),
};

// ── Static geometry ─────────────────────────────────────────────────────
const matBlack = new THREE.MeshBasicMaterial({ color: 0x111111 });
const sphO = new THREE.Mesh(new THREE.SphereGeometry(0.2, 24, 16), matBlack);
scene.add(sphO);

const PW = 3.6, PH = 4.6; // enlarged image plane dominates the left side
const planeMesh = new THREE.Mesh(
  new THREE.PlaneGeometry(PW, PH),
  new THREE.MeshBasicMaterial({ color: 0xcccccc, transparent: true, opacity: 0.22, side: THREE.DoubleSide, depthWrite: false }));
planeMesh.position.set(0, 0, F);
scene.add(planeMesh);

// Bold border frame built from cylinders (Line linewidth is unreliable)
const _up = new THREE.Vector3(0, 1, 0);
const matFrame = new THREE.MeshBasicMaterial({ color: 0x444444 });
const _frameGeo = new THREE.CylinderGeometry(1, 1, 1, 8);
function setCylBetween(mesh, a, b, r) {
  const dir = b.clone().sub(a);
  const len = dir.length();
  mesh.position.copy(a).addScaledVector(dir, 0.5);
  mesh.scale.set(r, len, r);
  mesh.quaternion.setFromUnitVectors(_up, dir.normalize());
}
{
  const hw = PW / 2, hh = PH / 2;
  const corners = [
    new THREE.Vector3(-hw, -hh, F), new THREE.Vector3(hw, -hh, F),
    new THREE.Vector3(hw, hh, F), new THREE.Vector3(-hw, hh, F)];
  for (let i = 0; i < 4; i++) {
    const m = new THREE.Mesh(_frameGeo, matFrame);
    setCylBetween(m, corners[i], corners[(i + 1) % 4], 0.035);
    scene.add(m);
  }
}

// ── Dynamic geometry ────────────────────────────────────────────────────
const sphP = new THREE.Mesh(new THREE.SphereGeometry(0.2, 24, 16), matBlack);
scene.add(sphP);
const sphp = new THREE.Mesh(new THREE.SphereGeometry(0.12, 24, 16), matBlack);
scene.add(sphp);

const matGreen = new THREE.MeshBasicMaterial({ color: 0x33dd33 });
const raySolid = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 10), matGreen);
scene.add(raySolid);

// Dashed green ray as a chain of short thick cylinder segments
const dashGroup = new THREE.Group();
scene.add(dashGroup);
const _dashGeo = new THREE.CylinderGeometry(1, 1, 1, 8);
function buildDashes(a, b, r) {
  while (dashGroup.children.length) dashGroup.remove(dashGroup.children[0]);
  const total = a.distanceTo(b);
  const dashLen = 0.34, gap = 0.2, step = dashLen + gap;
  const dir = b.clone().sub(a).normalize();
  for (let t = 0; t < total; t += step) {
    const t1 = Math.min(t + dashLen, total);
    if (t1 - t < 0.05) break;
    const m = new THREE.Mesh(_dashGeo, matGreen);
    setCylBetween(m, a.clone().addScaledVector(dir, t), a.clone().addScaledVector(dir, t1), r);
    dashGroup.add(m);
  }
}

// Thick custom red arrows (shaft cylinder + cone head), much bolder than ArrowHelper
const matRed = new THREE.MeshBasicMaterial({ color: 0xee1111 });
function makeThickArrow(shaftR, headR, headFrac) {
  const g = new THREE.Group();
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(1, 1, 1, 12), matRed);
  const head = new THREE.Mesh(new THREE.ConeGeometry(1, 1, 16), matRed);
  g.add(shaft); g.add(head);
  g.userData = { shaft, head, shaftR, headR, headFrac };
  scene.add(g);
  return g;
}
function aimThickArrow(g, origin, dirVec, len) {
  const { shaft, head, shaftR, headR, headFrac } = g.userData;
  const headLen = Math.min(len * headFrac, 0.55);
  const shaftLen = Math.max(len - headLen, 0.01);
  const d = dirVec.clone().normalize();
  g.position.copy(origin);
  g.quaternion.setFromUnitVectors(_up, d);
  shaft.scale.set(shaftR, shaftLen, shaftR);
  shaft.position.set(0, shaftLen / 2, 0);
  head.scale.set(headR, headLen, headR);
  head.position.set(0, shaftLen + headLen / 2, 0);
}
const arrowP = makeThickArrow(0.065, 0.18, 0.22);
const arrowp = makeThickArrow(0.05, 0.13, 0.3);

registerInteractive(sphP, {
  title: 'Point P in 3D',
  body: 'Drag me. The image point p always sits where the viewing ray from O pierces the image plane at z = f.',
  tooltip: 'Drag to move P'
});

// ── Labels (large serif, matching the book's hierarchy) ─────────────────
const SERIF = 'Georgia, "Times New Roman", serif';
function serifLabel(html, pos, px) {
  const e = addLabel(html, pos, { color: '#111', fontSize: px + 'px' });
  e.div.style.fontFamily = SERIF;
  return e;
}
const lblO = serifLabel('<i>o</i>', new THREE.Vector3(-0.45, -0.6, 0), 28);
const lblP = serifLabel('<b>P</b>', new THREE.Vector3(), 30);
const lblp = serifLabel('<b>p</b>', new THREE.Vector3(), 28);
const lblPd = serifLabel('<b>Ṗ</b>', new THREE.Vector3(), 32);
const lblpd = serifLabel('<b>ṗ</b>', new THREE.Vector3(), 30);

// ── Recompute everything from (P, Ṗ) ────────────────────────────────────
const _origin = new THREE.Vector3(0, 0, 0);
function recompute() {
  const P = state.P, v = state.vel;
  const t = F / P.z;
  const p = new THREE.Vector3(P.x * t, P.y * t, F);
  sphP.position.copy(P);
  sphp.position.copy(p);

  setCylBetween(raySolid, _origin, P.clone().multiplyScalar(1.08), RAY_R);

  const Pd = P.clone().addScaledVector(v, S);
  const td = F / Math.max(Pd.z, 0.3);
  const pd = new THREE.Vector3(Pd.x * td, Pd.y * td, F);
  buildDashes(_origin, Pd, RAY_R);

  // Ṗ arrow at P
  const vlen = v.length();
  if (vlen > 1e-4) {
    arrowP.visible = true;
    aimThickArrow(arrowP, P, v, S * vlen);
  } else arrowP.visible = false;

  // ṗ arrow at p toward p' (in the plane)
  const flow = pd.clone().sub(p); flow.z = 0;
  const flen = flow.length();
  if (flen > 1e-4) {
    arrowp.visible = true;
    aimThickArrow(arrowp, p, flow, flen);
  } else arrowp.visible = false;

  // labels — ṗ anchored directly at the arrow tip
  lblP.pos.copy(P).add(new THREE.Vector3(0.6, -0.05, 0));
  lblp.pos.copy(p).add(new THREE.Vector3(0.32, -0.5, 0));
  lblPd.pos.copy(P).addScaledVector(v, S).add(new THREE.Vector3(0, 0.55, 0));
  lblpd.pos.copy(p).add(flow).add(new THREE.Vector3(-0.1, 0.5, 0));
}
recompute();

// ── Camera (perspective) ────────────────────────────────────────────────
setCameraView({
  projection: 'perspective',
  azimuthDeg: 20, elevationDeg: 12, rollDeg: 0,
  target: [0.4, 0.2, 3.5],
  heightFraction: 0.6, distanceScale: 1.1,
});

// ── Sliders ─────────────────────────────────────────────────────────────
function bindSlider(id, comp) {
  const el = document.getElementById(id);
  const val = document.getElementById(id + 'val');
  el.addEventListener('input', () => {
    state.vel[comp] = parseFloat(el.value);
    val.textContent = el.value;
    recompute();
  });
}
bindSlider('velX', 'x'); bindSlider('velY', 'y'); bindSlider('velZ', 'z');

// ── Demo steps ──────────────────────────────────────────────────────────
const STEPS = [
  { vel: [-0.5, 1, -1],
    narration: "The figure's configuration: Ṗ has vertical and toward-camera components. The dashed ray to P+Ṗ pierces the plane exactly at the tip of the ṗ arrow — the 2D velocity is the projection of the 3D velocity." },
  { vel: [1.5, 0, 0],
    narration: 'Only Ẋ nonzero: ṗ becomes horizontal with magnitude f·Ẋ/Z — a clean rescaling. This is the component that behaves most intuitively.' },
  { vel: [0, 0, -1.5],
    narration: "Only Ż nonzero (moving toward the camera): p drifts outward from the principal point even though P's X and Y never change — perspective division by Z turns approach into looming expansion." },
];
let _tween = null;
function goToStep(i) {
  const st = STEPS[i];
  ['step0', 'step1', 'step2'].forEach((id, j) =>
    document.getElementById(id).classList.toggle('active', j === i));
  document.getElementById('narration').textContent = st.narration;
  const from = state.vel.clone();
  const to = new THREE.Vector3(...st.vel);
  if (_tween) cancelAnimationFrame(_tween);
  const t0 = performance.now();
  const step = (now) => {
    const k = Math.min(1, (now - t0) / 600);
    const e = k * (2 - k);
    state.vel.lerpVectors(from, to, e);
    ['velX', 'velY', 'velZ'].forEach((id, j) => {
      const val = state.vel.getComponent(j);
      document.getElementById(id).value = val;
      document.getElementById(id + 'val').textContent = val.toFixed(1);
    });
    recompute();
    if (k < 1) _tween = requestAnimationFrame(step);
  };
  _tween = requestAnimationFrame(step);
}
document.getElementById('step0').addEventListener('click', () => goToStep(0));
document.getElementById('step1').addEventListener('click', () => goToStep(1));
document.getElementById('step2').addEventListener('click', () => goToStep(2));
document.getElementById('narration').textContent = STEPS[0].narration;

// ── Drag P on a plane parallel to the image plane at P.z ────────────────
const _dragRay = new THREE.Raycaster();
const _ndc = new THREE.Vector2();
let _dragging = false;
function _setNdc(e) {
  const r = canvas.getBoundingClientRect();
  _ndc.x = ((e.clientX - r.left) / r.width) * 2 - 1;
  _ndc.y = -((e.clientY - r.top) / r.height) * 2 + 1;
}
canvas.addEventListener('pointerdown', (e) => {
  _setNdc(e);
  _dragRay.setFromCamera(_ndc, camera);
  if (_dragRay.intersectObject(sphP).length) {
    _dragging = true;
    controls.enabled = false;
    canvas.setPointerCapture(e.pointerId);
  }
});
canvas.addEventListener('pointermove', (e) => {
  if (!_dragging) return;
  _setNdc(e);
  _dragRay.setFromCamera(_ndc, camera);
  const dragPlane = new THREE.Plane(new THREE.Vector3(0, 0, 1), -state.P.z);
  const hit = new THREE.Vector3();
  if (_dragRay.ray.intersectPlane(dragPlane, hit)) {
    state.P.x = Math.max(-2, Math.min(3, hit.x));
    state.P.y = Math.max(-2, Math.min(2.5, hit.y));
    recompute();
  }
});
window.addEventListener('pointerup', () => {
  if (_dragging) { _dragging = false; controls.enabled = true; }
});
// @FIGURE_CODE_END

